solution:
pub type Student = {
  name: Str;
  grade: Int;
  gpa: Float64;
}

fn main() -> Int {
  let s1 = Student{ name: "Alice", grade: 85, gpa: 3.5 };
  let s2 = Student{ name: "Bob", grade: 92, gpa: 3.8 };
  let s3 = Student{ name: "Carol", grade: 78, gpa: 3.1 };
  return s1.grade + s2.grade + s3.grade;
}
